begin;
do $$
declare root uuid;u uuid[]:=array[gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid()];
 c1 uuid;c2 uuid;cm uuid;e1 uuid:=gen_random_uuid();e2 uuid:=gen_random_uuid();course_row public.courses;mc public.courses;
 r jsonb;p jsonb;q jsonb;v1 uuid;v2 uuid;other_v uuid;before_count integer;auth_count integer;i integer;current_ver integer;
 suffix text:=upper(replace(gen_random_uuid()::text,'-',''));id1 text;id2 text;id3 text;conflict_id text;archived_id text;rows jsonb;versions_before integer;
begin
 root:=(select user_id from public.user_profiles where role='main_admin' and retired_at is null and approval_status='approved');
 select * into strict course_row from public.courses where institution='ISAP' and active order by name limit 1;
 select * into strict mc from public.courses where institution='MCNP' and active order by name limit 1;
 for i in 1..5 loop
  insert into auth.users(id,email,email_confirmed_at) values(u[i],u[i]||'@test.invalid',now());
  insert into public.user_profiles(user_id,full_name) values(u[i],'Class fixture '||i);
 end loop;
 insert into public.events(id,name,institution,latitude,longitude,radius_meters,starts_at,ends_at) values(e1,'Roster event one','ISAP',17,121,100,now()+interval '2 days',now()+interval '3 days'),(e2,'Roster event two','ISAP',17,121,100,now()+interval '4 days',now()+interval '5 days');
 perform set_config('role','service_role',true);
 perform public.bootstrap_operational_administrator(root);
 perform public.save_operational_account(root,u[1],'classroom_representative','First rep',true,0,'[]','{}','Fixture provision');
 perform public.save_operational_account(root,u[2],'classroom_representative','Second rep',true,0,'[]','{}','Fixture provision');
 perform public.save_operational_account(root,u[3],'club_president','Assigned president',true,0,'[]','{}','Fixture provision');
 perform public.save_operational_account(root,u[4],'col_regular','Assigned staff',true,0,'[{"kind":"institution","scope_id":"ISAP"}]','{"representatives.assign":true,"sections.manage":true}','Fixture provision');
 perform public.save_operational_account(root,u[5],'col_admin','Other institution',true,0,'[{"kind":"institution","scope_id":"MCNP"}]','{}','Fixture provision');
 r:=public.save_class_section(root,null,0,jsonb_build_object('institution','ISAP','college',course_row.college,'course',course_row.name,'name','Class A '||suffix,'academic_year','2026-2027','term','First semester'),'Fixture section');c1:=(r->>'id')::uuid;
 r:=public.save_class_section(root,null,0,jsonb_build_object('institution','ISAP','college',course_row.college,'course',course_row.name,'name','Class B '||suffix,'academic_year','2026-2027','term','First semester'),'Fixture section');c2:=(r->>'id')::uuid;
 r:=public.save_class_section(root,null,0,jsonb_build_object('institution','MCNP','college',mc.college,'course',mc.name,'name','Other class '||suffix,'academic_year','2026-2027','term','First semester'),'Fixture section');cm:=(r->>'id')::uuid;
 if jsonb_array_length(public.list_class_sections(u[3])->'items')<>0 then raise exception 'FAIL: president inferred class ownership';end if;
 begin perform public.get_class_roster(u[3],c1);raise exception 'FAIL: unassigned roster read';exception when insufficient_privilege then null;end;
 begin perform public.save_class_section(u[5],c1,1,jsonb_build_object('name','Unauthorized','archived',false),'Cross institution');raise exception 'FAIL: cross-institution section edit';exception when insufficient_privilege then null;end;
 perform public.assign_class_officer(u[4],c1,u[1],'representative',1,false,'Appoint representative');
 begin perform public.assign_class_officer(root,c1,u[2],'representative',2,false,'Unconfirmed replacement');raise exception 'FAIL: replacement without confirmation';exception when sqlstate '22023' then null;end;
 begin insert into public.class_assignments(section_id,user_id,kind,role_at_assignment,assigned_by,reason) values(c1,u[2],'representative','classroom_representative',root,'Bypass test');raise exception 'FAIL: database representative uniqueness';exception when unique_violation then null;end;
 begin perform public.assign_class_officer(root,c1,u[3],'representative',2,true,'Wrong role');raise exception 'FAIL: president becomes representative';exception when sqlstate '22023' then null;end;
 perform public.assign_class_officer(root,c1,u[2],'representative',2,true,'Reviewed replacement');
 begin perform public.assign_class_officer(root,c1,u[1],'editor',3,false,'Second representative via editor');raise exception 'FAIL: representative bypass through editor role';exception when sqlstate '22023' then null;end;
 if app_private.operational_capable(u[1],'rosters.view','section',c1::text) or not app_private.operational_capable(u[2],'rosters.manage','section',c1::text) then raise exception 'FAIL: representative replacement permissions';end if;
 perform public.assign_class_officer(root,c1,u[3],'editor',3,false,'Assigned class editor');
 if not app_private.operational_capable(u[3],'rosters.manage','section',c1::text) or app_private.operational_capable(u[3],'rosters.manage','section',c2::text) then raise exception 'FAIL: explicit president class scope';end if;
 select version into current_ver from public.operational_accounts where user_id=u[2];
 perform public.save_operational_account(root,u[2],'classroom_representative','Second rep',true,current_ver,'[]','{"representatives.assign":true}','Role restrictions still apply');
 if app_private.operational_capable(u[2],'representatives.assign') then raise exception 'FAIL: representative can delegate sensitive class access';end if;
 begin perform public.get_class_roster(u[3],c2);raise exception 'FAIL: cross-class access';exception when insufficient_privilege then null;end;
 p:=public.preview_class_roster(u[3],c1,'[{"row_number":2,"school_id":"FORMULA-NAME","full_name":"=Formula-like text"}]','formula.xlsx','merge');
 if (p->>'valid_count')::int<>0 then raise exception 'FAIL: server accepted formula-prefixed name';end if;
 begin perform public.assign_class_officer(u[4],cm,u[1],'representative',1,false,'Cross-institution assignment');raise exception 'FAIL: cross-institution assignment';exception when insufficient_privilege then null;end;
 id1:='0000'||left(suffix,16);id2:='ID2-'||left(suffix,16);id3:='ID3-'||left(suffix,16);conflict_id:='CONFLICT-'||left(suffix,16);archived_id:='ARCHIVED-'||left(suffix,16);
 insert into public.students(name,student_number,student_token,institution,college,course,archived_at) values('Other identity',conflict_id,gen_random_uuid()::text,'ISAP',course_row.college,course_row.name,null),('Archived identity',archived_id,gen_random_uuid()::text,'ISAP',course_row.college,course_row.name,now());
 rows:=jsonb_build_array(jsonb_build_object('row_number',2,'school_id',id1,'full_name','Participant One'),jsonb_build_object('row_number',3,'school_id',lower(id2),'full_name','Participant Two'),jsonb_build_object('row_number',4,'school_id',id3,'full_name','Duplicate'),jsonb_build_object('row_number',5,'school_id',id3,'full_name','Duplicate'),jsonb_build_object('row_number',6,'school_id','','full_name','Numeric ID','error','School ID must be text'),jsonb_build_object('row_number',7,'school_id',conflict_id,'full_name','Someone Else'),jsonb_build_object('row_number',8,'school_id',archived_id,'full_name','Archived identity'));
 p:=public.preview_class_roster(u[3],c1,rows,'official.xlsx','merge');
 if (p->>'valid_count')::int<>2 or (p->>'rejected_count')::int<>5 or p::text like '%Other identity%' then raise exception 'FAIL: validation or cross-class identity disclosure';end if;
 begin perform public.commit_class_roster(u[3],(p->>'id')::uuid,false,false,'Unconfirmed partial import');raise exception 'FAIL: silently dropped rejected rows';exception when sqlstate '22023' then null;end;
 select count(*) into auth_count from public.user_profiles;
 r:=public.commit_class_roster(u[3],(p->>'id')::uuid,true,false,'Reviewed valid subset');v1:=(r->>'version_id')::uuid;
 if (select count(*) from public.user_profiles)<>auth_count or (r->>'row_count')::int<>2 or not exists(select 1 from public.class_roster_entries where version_id=v1 and school_id=id1) then raise exception 'FAIL: import creates accounts or loses leading zeroes';end if;
 r:=public.commit_class_roster(u[3],(p->>'id')::uuid,true,false,'Retry same request');if (r->>'version_id')::uuid<>v1 or (r->>'replayed')::boolean is not true then raise exception 'FAIL: idempotent retry';end if;
 rows:=jsonb_build_array(jsonb_build_object('row_number',2,'school_id',id1,'full_name','Participant One'),jsonb_build_object('row_number',3,'school_id',id2,'full_name','Participant Two'));
 p:=public.preview_class_roster(u[3],c1,rows,'same.xlsx','merge');r:=public.commit_class_roster(u[3],(p->>'id')::uuid,false,false,'Repeated upload');if (r->>'changed')::boolean or (r->>'version_id')::uuid<>v1 then raise exception 'FAIL: identical upload creates a version';end if;
 perform public.set_event_class_rosters(root,e1,0,jsonb_build_array(c1),'Select official list');perform public.set_event_class_rosters(root,e2,0,jsonb_build_array(c1),'Reuse official list');
 if not app_private.operational_capable(u[2],'events.view','event',e1::text) or app_private.operational_capable(u[2],'events.eligibility','event',e1::text) then raise exception 'FAIL: bound class event visibility/management boundary';end if;
 p:=public.preview_class_roster(u[3],c1,jsonb_build_array(jsonb_build_object('row_number',2,'school_id',id3,'full_name','Participant Three')),'update.xlsx','merge');
 r:=public.commit_class_roster(u[3],(p->>'id')::uuid,false,false,'Add participant');v2:=(r->>'version_id')::uuid;
 if (r->>'row_count')::int<>3 or (select count(*) from public.class_roster_entries where version_id=v1)<>2 then raise exception 'FAIL: merge or immutable old snapshot';end if;
 if exists(select 1 from public.event_eligibility_heads h join public.event_eligibility_rosters b on b.eligibility_id=h.eligibility_id where h.event_id in(e1,e2) and b.roster_version_id<>v1) then raise exception 'FAIL: roster edit changed event history';end if;
 if (public.get_class_roster(u[3],c1,v1)->>'total')::int<>2 then raise exception 'FAIL: historic roster view';end if;
 perform public.set_event_class_rosters(root,e1,1,jsonb_build_array(c1),'Explicitly refresh eligible version');
 update public.events set starts_at=now()+interval '30 minutes' where id=e1;
 p:=public.preview_class_roster(root,c2,rows,'reuse.xlsx','merge');r:=public.commit_class_roster(root,(p->>'id')::uuid,false,false,'Reuse same identities in another class');other_v:=(r->>'version_id')::uuid;
 if (select count(distinct student_id) from public.class_roster_entries where school_id=id1)<>1 then raise exception 'FAIL: global student identity not reused';end if;
 begin perform public.get_class_roster(u[3],c1,other_v);raise exception 'FAIL: cross-class version injection';exception when sqlstate '22023' then null;end;
 p:=public.preview_class_roster(u[3],c1,rows,'owner.xlsx','merge');
 begin perform public.commit_class_roster(root,(p->>'id')::uuid,false,false,'Steal preview');raise exception 'FAIL: preview owner isolation';exception when insufficient_privilege then null;end;
 update public.students set name='Changed after preview' where upper(btrim(student_number))=id1;
 begin perform public.commit_class_roster(u[3],(p->>'id')::uuid,false,false,'Stale identity');raise exception 'FAIL: identity race accepted';exception when serialization_failure then null;end;
 update public.students set name='Participant One' where upper(btrim(student_number))=id1;
 update public.class_roster_previews set expires_at=now()-interval '1 minute' where id=(p->>'id')::uuid;
 begin perform public.commit_class_roster(u[3],(p->>'id')::uuid,false,false,'Expired preview');raise exception 'FAIL: expired preview';exception when serialization_failure then null;end;
 p:=public.preview_class_roster(u[3],c1,jsonb_build_array(jsonb_build_object('row_number',2,'school_id',id1,'full_name','Participant One')),'replace.xlsx','replace');
 begin perform public.commit_class_roster(u[3],(p->>'id')::uuid,false,false,'Unconfirmed replacement');raise exception 'FAIL: silent roster replacement';exception when sqlstate '22023' then null;end;
 r:=public.commit_class_roster(u[3],(p->>'id')::uuid,false,true,'Reviewed replacement');
 if (r->>'row_count')::int<>1 or (select count(*) from public.class_roster_entries where version_id=v1)<>2 or (select count(*) from public.class_roster_entries where version_id=v2)<>3 then raise exception 'FAIL: replace erased historical membership';end if;
 begin perform public.set_event_class_rosters(root,e1,2,jsonb_build_array(c1),'Late eligibility change');raise exception 'FAIL: open event eligibility changed';exception when sqlstate '22023' then null;end;
 if not exists(select 1 from public.event_eligibility_heads h join public.event_eligibility_rosters b on b.eligibility_id=h.eligibility_id where h.event_id=e2 and b.roster_version_id=v1) then raise exception 'FAIL: reused event snapshot changed';end if;
 p:=public.preview_class_roster(u[3],c1,rows,'pending.xlsx','merge');
 select version into current_ver from public.operational_accounts where user_id=u[3];
 perform public.save_operational_account(root,u[3],'col_regular','Changed role',true,current_ver,'[]','{}','Role changed after assignment');
 if app_private.operational_capable(u[3],'rosters.view','section',c1::text) then raise exception 'FAIL: role change retained class assignment';end if;
 begin perform public.commit_class_roster(u[3],(p->>'id')::uuid,false,false,'Revoked editor');raise exception 'FAIL: revoked editor committed';exception when insufficient_privilege then null;end;
 begin update public.class_roster_entries set full_name='History tamper' where version_id=v1;raise exception 'FAIL: mutable historic membership';exception when sqlstate '22023' then null;end;
 begin delete from public.class_roster_versions where id=v1;raise exception 'FAIL: deletable historical roster';exception when sqlstate '22023' then null;end;
 select version into current_ver from public.class_sections where id=c1;
 perform public.save_class_section(root,c1,current_ver,jsonb_build_object('name','Archived fixture '||suffix,'archived',true),'Archive preserving history');
 if (public.get_class_roster(root,c1,v1)->>'total')::int<>2 then raise exception 'FAIL: archive hid historical roster';end if;
 if (public.get_event_class_rosters(root,e2)->'rosters'->0->>'name') not like 'Class A %' then raise exception 'FAIL: section rename rewrote event roster labels';end if;
 begin perform public.preview_class_roster(root,c1,rows,'archived.xlsx','merge');raise exception 'FAIL: archived class writable';exception when sqlstate '22023' then null;end;
 for r in select jsonb_build_object('sig',p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in('save_class_section','assign_class_officer','list_class_sections','class_assignment_candidates','get_class_roster','preview_class_roster','commit_class_roster','set_event_class_rosters','get_event_class_rosters','get_operational_access','get_operational_access_base') loop
  if has_function_privilege('anon',r->>'sig','EXECUTE') or has_function_privilege('authenticated',r->>'sig','EXECUTE') then raise exception 'FAIL: browser class RPC privilege';end if;
 end loop;
 if has_table_privilege('authenticated','public.class_roster_entries','SELECT') or has_table_privilege('anon','public.class_roster_previews','SELECT') then raise exception 'FAIL: browser roster table privileges';end if;
end $$;
select 'PASS: class scopes, representative uniqueness/replacement, import validation, identity isolation, immutable versions, event snapshots, retries, revocation and archive preservation' as result;
rollback;
